import Button from '@mui/material/Button';
import '../styles/Cart.css';
import { useState } from 'react';

function Cart({ cart, updateCart }) {
    const tshirtPrice = 20;
    return (
        <div className='cart'>
            <h2>Panier</h2>
            <div className="total">
                Total : {tshirtPrice * cart}€
            </div>
            <br />
            <button onClick={() => updateCart(0)}>
                Vider le panier
            </button>
        </div>
    );
}


export default Cart
